```csharp
// PUT: api/users/update
[HttpPut("{update}")]
public async Task<IActionResult> UpdateUser([FromBody] UpdateUserRequest model)
{
    if (!ModelState.IsValid)
    {
        return BadRequest(ModelState);
    }

    try
    {
        await _userService.UpdateUserAsync(model);
    }
    catch (Exception exp)
    {
        return BadRequest(exp);
    }

    return NoContent();
}
```

Route "/api/users/{update}" declares {update} but UpdateUser has no parameter named "update"; PUT /api/users/anything would match too. If a literal segment was intended, write "update" without braces.

